use Wikibase\DataModel\Entity\EntityId;
use Wikibase\DataModel\Statement\Statement;

class StatementProcessor {
    private $entityId;
    private $claimGuidGenerator;

    public function __construct(EntityId $entityId, ClaimGuidGenerator $claimGuidGenerator) {
        $this->entityId = $entityId;
        $this->claimGuidGenerator = $claimGuidGenerator;
    }

    public function processStatement(?Statement $statement): string {
        if ($statement === null) {
            $statementId = $this->entityId . '$' . $this->claimGuidGenerator->generate();
        } else {
            $statementId = $statement->getId();
        }
        return $statementId;
    }
}
