private function computeActionChoices(Replacer $replacer): array {
    $choices = [];
    foreach ($replacer->choices as $choice) {
        $mode = $this->determineModeFromChoice($choice);
        if ($this->isValidMode($mode)) {
            $choices[] = [
                'label' => $choice['label'],
                'action' => new Action($mode),
            ];
        }
    }
    return $choices;
}

private function determineModeFromChoice(array $choice): string {
    // Logic to determine the mode based on the choice properties
    return $choice['type'];
}

private function isValidMode(string $mode): bool {
    // List of valid modes
    $validModes = ['edit', 'delete', 'view'];
    return in_array($mode, $validModes);
}
