const { rest } = require('some-rest-library');
const mw = require('mediawiki');

class CodeMirrorLint {
	constructor(restClient) {
		this.restClient = restClient;
		this.currentRequest = null;
	}

	async lint(doc) {
		if (this.currentRequest) {
			this.currentRequest.abort();
		}

		try {
			this.currentRequest = this.restClient.post('/v1/transform/wikitext/to/lint', {
				wikitext: doc.toString(),
				timeout: 30000 // Default timeout of 30 seconds
			});

			const response = await this.currentRequest;
			return response.data;
		} catch (error) {
			mw.log.warn('[CodeMirror] Lint request failed:', error);
			throw error;
		} finally {
			this.currentRequest = null;
		}
	}
}
```

This revision addresses the review comments by adding a timeout and aborting previous requests before making a new one. It also includes error handling and logging.

