<?php

class LanguageLoader {
    private $supportedLanguages;

    public function __construct() {
        $this->loadSupportedLanguages();
    }

    private function loadSupportedLanguages(): void {
        $languagesJsonPath = __DIR__ . '/../../languages.json';
        if (file_exists($languagesJsonPath)) {
            $jsonContent = file_get_contents($languagesJsonPath);
            $this->supportedLanguages = json_decode($jsonContent, true) ?? [];
        } else {
            $this->supportedLanguages = [];
        }
    }

    public function getSupportedLanguages(): array {
        return $this->supportedLanguages;
    }
}

// Usage
$languageLoader = new LanguageLoader();
$supportedLanguages = $languageLoader->getSupportedLanguages();
